mapper.select:
SELECT o.*, u.user_name, wu.user_name AS wasteUserName FROM waste_order o LEFT JOIN tb_user u ON o.user_id = u.user_id LEFT JOIN tb_user wu ON o.waste_user_id = wu.user_id
and o.user_id = #{param.userId}
and p.order_no like concat('%', #{param.orderNo} ,'%')
and o.status = #{param.status}
and o.waste_user_id = #{param.wasteUserId}
and wu.user_name like concat('%', #{param.wasteUserName} ,'%')
and u.user_name like concat('%', #{param.userName} ,'%')
ORDER BY o.create_time DESC
